CREATE OR REPLACE FUNCTION public.create_order_atomic(p_order_type text, p_customer_user_id uuid, p_provider_org_id uuid DEFAULT NULL::uuid, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_total_amount numeric DEFAULT 0, p_currency text DEFAULT 'THB'::text, p_notes text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_items jsonb DEFAULT '[]'::jsonb, p_participants jsonb DEFAULT '[]'::jsonb, p_addresses jsonb DEFAULT '[]'::jsonb, p_payment_method text DEFAULT NULL::text, p_payment_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_item JSONB;
  v_participant JSONB;
  v_address JSONB;
BEGIN
  -- Create order
  INSERT INTO public.orders (
    order_type, customer_user_id, provider_org_id,
    status, start_at, end_at, total_amount, currency, notes, metadata
  ) VALUES (
    p_order_type, p_customer_user_id, p_provider_org_id,
    'pending', p_start_at, p_end_at, p_total_amount, p_currency, p_notes, p_metadata
  )
  RETURNING id, order_number INTO v_order_id, v_order_number;

  -- Insert items
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      INSERT INTO public.order_items (
        order_id, product_id, resource_id, provider_org_id,
        item_name, item_type, qty, unit_price, amount, 
        start_at, end_at, metadata
      ) VALUES (
        v_order_id,
        NULLIF(v_item->>'product_id', '')::uuid,
        NULLIF(v_item->>'resource_id', '')::uuid,
        COALESCE(NULLIF(v_item->>'provider_org_id', '')::uuid, p_provider_org_id),
        v_item->>'item_name',
        COALESCE(v_item->>'item_type', 'service'),
        COALESCE((v_item->>'qty')::int, 1),
        COALESCE((v_item->>'unit_price')::numeric, 0),
        COALESCE((v_item->>'amount')::numeric, 0),
        NULLIF(v_item->>'start_at', '')::timestamptz,
        NULLIF(v_item->>'end_at', '')::timestamptz,
        COALESCE(v_item->'metadata', '{}'::jsonb)
      );
    END LOOP;
  END IF;

  -- Insert participants
  IF p_participants IS NOT NULL AND jsonb_array_length(p_participants) > 0 THEN
    FOR v_participant IN SELECT * FROM jsonb_array_elements(p_participants)
    LOOP
      INSERT INTO public.order_participants (
        order_id, role, name, phone, email
      ) VALUES (
        v_order_id,
        COALESCE(v_participant->>'role', 'primary'),
        v_participant->>'name',
        v_participant->>'phone',
        v_participant->>'email'
      );
    END LOOP;
  END IF;

  -- Insert addresses
  IF p_addresses IS NOT NULL AND jsonb_array_length(p_addresses) > 0 THEN
    FOR v_address IN SELECT * FROM jsonb_array_elements(p_addresses)
    LOOP
      INSERT INTO public.order_addresses (
        order_id, address_type, address_text, lat, lng, notes
      ) VALUES (
        v_order_id,
        v_address->>'address_type',
        v_address->>'address_text',
        NULLIF(v_address->>'lat', '')::numeric,
        NULLIF(v_address->>'lng', '')::numeric,
        v_address->>'notes'
      );
    END LOOP;
  END IF;

  -- Create payment intent if provided (cast text to payment_method enum)
  IF p_payment_method IS NOT NULL AND p_payment_amount IS NOT NULL THEN
    INSERT INTO public.payment_intents (
      order_id, amount, currency, method, status
    ) VALUES (
      v_order_id, p_payment_amount, p_currency, p_payment_method::payment_method, 'pending'
    );
  END IF;

  -- Record initial status in history
  INSERT INTO public.order_status_history (
    order_id, from_status, to_status, actor_user_id, reason
  ) VALUES (
    v_order_id, NULL, 'pending', p_customer_user_id, 'Order created'
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_sync_order_to_property_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_property_id uuid; v_owner_id uuid; v_guest_name text; v_guest_phone text; v_guest_email text;
  v_guests_count int; v_check_in date; v_check_out date; v_status text; v_source text; v_item_meta jsonb;
  v_deposit numeric;
BEGIN
  IF COALESCE(NEW.vertical, OLD.vertical) <> 'property' THEN RETURN NEW; END IF;
  SELECT COALESCE(oi.resource_id::uuid, (oi.metadata->>'property_id')::uuid), oi.metadata
    INTO v_property_id, v_item_meta
  FROM order_items oi WHERE oi.order_id = NEW.id AND oi.item_type = 'property' LIMIT 1;
  IF v_property_id IS NULL THEN RETURN NEW; END IF;
  SELECT owner_id INTO v_owner_id FROM properties WHERE id = v_property_id;
  SELECT name, phone, email INTO v_guest_name, v_guest_phone, v_guest_email
  FROM order_participants WHERE order_id = NEW.id AND role IN ('guest','primary')
    ORDER BY (role = 'guest') DESC LIMIT 1;
  v_check_in := (NEW.start_at::timestamptz)::date;
  v_check_out := (NEW.end_at::timestamptz)::date;
  v_guests_count := COALESCE(NULLIF(NEW.metadata->>'guests_count','')::int,
    NULLIF(NEW.metadata->>'guests','')::int, NULLIF(v_item_meta->>'guests','')::int, 1);
  v_deposit := NULLIF(COALESCE(NEW.metadata->>'deposit_amount', v_item_meta->>'deposit_amount'),'')::numeric;
  v_source := COALESCE(NULLIF(NEW.metadata->>'source', ''), 'manual');
  v_status := CASE
    WHEN NEW.deleted_at IS NOT NULL THEN 'cancelled'
    WHEN NEW.status IN ('cancelled','refunded','expired') THEN 'cancelled'
    -- Preserve lifecycle labels without implicitly releasing no-show inventory.
    WHEN NEW.status IN ('confirmed','completed','checked_in','checked_out','no_show') THEN NEW.status::text
    ELSE 'pending' END;
  UPDATE property_bookings SET external_id = NEW.id::text
  WHERE external_id IS NULL AND property_id = v_property_id
    AND check_in = v_check_in AND check_out = v_check_out
    AND NOT EXISTS (SELECT 1 FROM property_bookings pb2 WHERE pb2.external_id = NEW.id::text);
  BEGIN
    INSERT INTO property_bookings (property_id, owner_id, guest_name, guest_phone, guest_email,
      guests_count, check_in, check_out, total_amount, currency, source, external_id, status, notes,
      deposit_amount, created_at, updated_at)
    VALUES (v_property_id, v_owner_id, COALESCE(v_guest_name,'Guest'), v_guest_phone, v_guest_email,
      v_guests_count, v_check_in, v_check_out, NEW.total_amount, NEW.currency, v_source, NEW.id::text, v_status, NEW.notes,
      v_deposit, NEW.created_at, NEW.updated_at)
    ON CONFLICT (external_id) DO UPDATE SET
      property_id = EXCLUDED.property_id, owner_id = EXCLUDED.owner_id, guest_name = EXCLUDED.guest_name,
      guest_phone = EXCLUDED.guest_phone, guest_email = EXCLUDED.guest_email, guests_count = EXCLUDED.guests_count,
      check_in = EXCLUDED.check_in, check_out = EXCLUDED.check_out, total_amount = EXCLUDED.total_amount,
      currency = EXCLUDED.currency, status = EXCLUDED.status, notes = EXCLUDED.notes,
      deposit_amount = COALESCE(EXCLUDED.deposit_amount, property_bookings.deposit_amount), updated_at = now();
  EXCEPTION WHEN exclusion_violation THEN
    INSERT INTO reconciliation_alerts (alert_type, severity, order_id, expected_amount, currency, description, details)
    SELECT 'booking_overlap', 'high', NEW.id, NEW.total_amount, NEW.currency,
      'Order dates overlap an existing booking for this property',
      jsonb_build_object('property_id', v_property_id, 'check_in', v_check_in, 'check_out', v_check_out)
    WHERE NOT EXISTS (SELECT 1 FROM reconciliation_alerts ra WHERE ra.order_id = NEW.id AND ra.alert_type = 'booking_overlap' AND ra.resolved_at IS NULL);
  END;
  RETURN NEW;
END;
$function$
